# Simulation benchmark analysis -----
#
# Collects completed seven-model benchmark campaigns, constructs their strict
# common support and reports the main network-recovery comparisons.
#
# Full campaign outputs are generated by the benchmark runners and are not
# distributed with the repository.


rm(list = ls())


# Setup -----

library(data.table)

benchmark_root <- file.path(
  "outputs",
  "benchmark_runs"
)

models <- c(
  "m3",
  "gigg",
  "half_t",
  "adelie_gen",
  "bigvar_hlag",
  "mar",
  "nirvar"
)

model_labels <- c(
  m3 = "M3",
  gigg = "GIGG",
  half_t = "Half-t",
  adelie_gen = "gEN",
  bigvar_hlag = "HLAG",
  mar = "MAR",
  nirvar = "NIRVAR"
)

ordinary_families <- c(
  "blockdiag",
  "communities",
  "coreperiphery",
  "hubs"
)

topology_labels <- c(
  blockdiag = "Block diagonal",
  communities = "Communities",
  coreperiphery = "Core-periphery",
  hubs = "Hubs"
)

metrics <- c(
  "lag_pr_auc",
  "unit_max_pr_auc",
  "unit_rms_rmse",
  "unit_rms_rmse_active",
  "unit_rms_inactive_leakage",
  "mean_false",
  "maximum_false",
  "self_block_rmse"
)

metric_info <- data.table(
  metric = metrics,
  metric_label = c(
    "Lag PR-AUC",
    "Unit PR-AUC",
    "Unit RMSE",
    "Active RMSE",
    "Inactive leakage",
    "Mean false strength",
    "Maximum false strength",
    "Self-block RMSE"
  ),
  higher_better = c(
    TRUE,
    TRUE,
    FALSE,
    FALSE,
    FALSE,
    FALSE,
    FALSE,
    FALSE
  )
)


# Helpers -----

finite_mean <- function(x) {
  x <- x[is.finite(x)]
  if (!length(x)) return(NA_real_)
  mean(x)
}


read_model_results <- function(model) {
  model_root <- file.path(
    benchmark_root,
    model
  )
  
  files <- list.files(
    model_root,
    pattern = "^benchmark\\.rds$",
    recursive = TRUE,
    full.names = TRUE
  )
  
  if (!length(files)) {
    stop(
      "No benchmark outputs found for ",
      model,
      " under ",
      model_root
    )
  }
  
  results <- rbindlist(
    lapply(files, function(file) {
      object <- readRDS(file)
      
      if (is.null(object$results)) {
        stop(
          "Missing results table in ",
          file
        )
      }
      
      as.data.table(object$results)
    }),
    use.names = TRUE,
    fill = TRUE
  )
  
  required <- c(
    "record_id",
    "dgp_id",
    "seed",
    "T_obs",
    "model",
    metrics
  )
  
  missing <- setdiff(
    required,
    names(results)
  )
  
  if (length(missing)) {
    stop(
      "Missing columns for ",
      model,
      ": ",
      paste(missing, collapse = ", ")
    )
  }
  
  results <- results[results[["model"]] == model]
  results[, family := sub("_n[0-9]+_m[0-9]+_p[0-9]+$", "", dgp_id)]
  results <- results[family %in% ordinary_families]
  results[, cell_key := paste(dgp_id, T_obs, seed, sep = "::")]
  
  if (anyDuplicated(results$cell_key)) {
    stop(
      "Duplicate simulation cells for ",
      model
    )
  }
  
  if (anyDuplicated(results$record_id)) {
    stop(
      "Duplicate record IDs for ",
      model
    )
  }
  
  results
}


# Load benchmark outputs -----

model_results <- setNames(
  lapply(models, read_model_results),
  models
)

inventory <- rbindlist(
  lapply(models, function(model) {
    x <- model_results[[model]]
    
    data.table(
      model = model_labels[[model]],
      DGPs = uniqueN(x$dgp_id),
      T_values = uniqueN(x$T_obs),
      seeds = uniqueN(x$seed),
      cells = nrow(x)
    )
  })
)


# Common support -----

support <- rbindlist(
  lapply(models, function(model) {
    x <- model_results[[model]]
    
    x[, .(
      model,
      cell_key,
      dgp_id,
      T_obs,
      seed
    )]
  })
)

common_keys_raw <- support[
  ,
  .(
    models_present = uniqueN(model)
  ),
  by = cell_key
][
  models_present == length(models),
  cell_key
]

common_meta <- unique(
  support[
    cell_key %in% common_keys_raw,
    .(
      cell_key,
      dgp_id,
      T_obs,
      seed
    )
  ]
)

common_T <- sort(
  unique(common_meta$T_obs)
)

common_seeds <- sort(
  unique(common_meta$seed)
)

expected_cells_per_dgp <-
  length(common_T) *
  length(common_seeds)

dgp_grid <- common_meta[
  ,
  .(
    cells = .N,
    T_values = uniqueN(T_obs),
    seeds = uniqueN(seed)
  ),
  by = dgp_id
]

complete_dgps <- dgp_grid[
  cells == expected_cells_per_dgp &
    T_values == length(common_T) &
    seeds == length(common_seeds),
  dgp_id
]

common_keys <- common_meta[
  dgp_id %in% complete_dgps,
  cell_key
]

benchmark <- rbindlist(
  lapply(models, function(model) {
    model_results[[model]][
      cell_key %in% common_keys
    ]
  }),
  use.names = TRUE,
  fill = TRUE
)

if (
  nrow(benchmark) !=
  length(common_keys) * length(models)
) {
  stop(
    "Balanced common support is incomplete."
  )
}

benchmark[, model_label := model_labels[model]]
benchmark[, topology := topology_labels[family]]

setorder(
  benchmark,
  topology,
  dgp_id,
  T_obs,
  seed,
  model
)

endpoint_T <- range(
  benchmark$T_obs
)


# Metric summaries -----

benchmark_long <- melt(
  benchmark,
  id.vars = c(
    "cell_key",
    "dgp_id",
    "family",
    "topology",
    "T_obs",
    "seed",
    "model",
    "model_label"
  ),
  measure.vars = metrics,
  variable.name = "metric",
  value.name = "value"
)

benchmark_long <- merge(
  benchmark_long,
  metric_info,
  by = "metric",
  all.x = TRUE,
  sort = FALSE
)


# Block-diagonal recovery -----

blockdiag_metrics <- c(
  "mean_false",
  "maximum_false",
  "self_block_rmse"
)

blockdiag_summary <- benchmark_long[
  family == "blockdiag" &
    metric %in% blockdiag_metrics,
  .(
    estimate = finite_mean(value)
  ),
  by = .(
    T_obs,
    model,
    model_label,
    metric,
    metric_label
  )
]

blockdiag_winners <- blockdiag_summary[
  is.finite(estimate),
  .SD[which.min(estimate)],
  by = .(
    T_obs,
    metric_label
  )
]

blockdiag_winners <- blockdiag_winners[
  ,
  .(
    T_obs,
    metric = metric_label,
    model = model_label,
    mean = estimate
  )
]


# Controlled-network recovery -----

controlled_metrics <- c(
  "lag_pr_auc",
  "unit_max_pr_auc",
  "unit_rms_rmse",
  "unit_rms_rmse_active",
  "unit_rms_inactive_leakage"
)

controlled_summary <- benchmark_long[
  family != "blockdiag" &
    metric %in% controlled_metrics,
  .(
    estimate = finite_mean(value)
  ),
  by = .(
    T_obs,
    model,
    model_label,
    metric,
    metric_label,
    higher_better
  )
]

controlled_winners <- controlled_summary[
  T_obs %in% endpoint_T &
    is.finite(estimate),
  .SD[
    which.max(
      if (higher_better[1L]) {
        estimate
      } else {
        -estimate
      }
    )
  ],
  by = .(
    T_obs,
    metric_label
  )
]

controlled_winners <- controlled_winners[
  ,
  .(
    T_obs,
    metric = metric_label,
    model = model_label,
    mean = estimate
  )
]


# Topology-specific recovery -----

topology_metrics <- c(
  "lag_pr_auc",
  "unit_max_pr_auc",
  "unit_rms_rmse_active",
  "unit_rms_inactive_leakage"
)

topology_summary <- benchmark_long[
  family != "blockdiag" &
    metric %in% topology_metrics,
  .(
    estimate = finite_mean(value)
  ),
  by = .(
    topology,
    T_obs,
    model,
    model_label,
    metric,
    metric_label,
    higher_better
  )
]

topology_winners <- topology_summary[
  T_obs %in% endpoint_T &
    is.finite(estimate),
  .SD[
    which.max(
      if (higher_better[1L]) {
        estimate
      } else {
        -estimate
      }
    )
  ],
  by = .(
    topology,
    T_obs,
    metric_label
  )
]

topology_winners <- topology_winners[
  ,
  .(
    topology,
    T_obs,
    metric = metric_label,
    model = model_label,
    mean = estimate
  )
]


# M3 and GIGG trade-off -----

m3_gigg <- benchmark[
  family != "blockdiag" &
    model %in% c(
      "m3",
      "gigg"
    ),
  .(
    active_rmse =
      finite_mean(
        unit_rms_rmse_active
      ),
    inactive_leakage =
      finite_mean(
        unit_rms_inactive_leakage
      )
  ),
  by = .(
    topology,
    T_obs,
    model
  )
]

m3_gigg <- dcast(
  m3_gigg,
  topology + T_obs ~ model,
  value.var = c(
    "active_rmse",
    "inactive_leakage"
  )
)

m3_gigg[
  ,
  `:=`(
    gigg_over_m3_active =
      active_rmse_gigg /
      active_rmse_m3,
    gigg_over_m3_leakage =
      inactive_leakage_gigg /
      inactive_leakage_m3
  )
]

m3_gigg <- m3_gigg[
  ,
  .(
    topology,
    T_obs,
    M3_active_RMSE =
      active_rmse_m3,
    GIGG_active_RMSE =
      active_rmse_gigg,
    GIGG_over_M3_active =
      gigg_over_m3_active,
    M3_inactive_leakage =
      inactive_leakage_m3,
    GIGG_inactive_leakage =
      inactive_leakage_gigg,
    GIGG_over_M3_leakage =
      gigg_over_m3_leakage
  )
]

setorder(
  m3_gigg,
  topology,
  T_obs
)


# Headline results -----

cat(
  "\nSIMULATION BENCHMARK ANALYSIS\n",
  "=============================\n\n",
  sep = ""
)

cat(
  "MODEL COVERAGE\n"
)

print(
  inventory
)

cat(
  "\nCOMMON SUPPORT\n",
  "Raw seven-model cells: ",
  length(common_keys_raw),
  "\n",
  "Complete common DGPs: ",
  length(complete_dgps),
  "\n",
  "Balanced common cells: ",
  length(common_keys),
  "\n",
  "Model fits analysed: ",
  nrow(benchmark),
  "\n",
  "T values: ",
  paste(common_T, collapse = ", "),
  "\n",
  "Seeds: ",
  length(common_seeds),
  "\n",
  sep = ""
)

cat(
  "\nBLOCK-DIAGONAL WINNERS\n"
)

print(
  blockdiag_winners,
  digits = 5
)

cat(
  "\nCONTROLLED-NETWORK ENDPOINT WINNERS\n"
)

print(
  controlled_winners,
  digits = 5
)

cat(
  "\nTOPOLOGY-SPECIFIC ENDPOINT WINNERS\n"
)

print(
  topology_winners,
  digits = 5
)

cat(
  "\nM3-GIGG TRADE-OFF\n"
)

print(
  m3_gigg,
  digits = 5
)